import fs from 'node:fs/promises'
import path from 'node:path'
import matter from 'gray-matter'
import { z } from 'zod'

const Post = z.object({ title: z.string(), date: z.coerce.date(), draft: z.boolean().optional() })
const dir = path.join(process.cwd(), 'content/blog')

export async function getPosts() {
  const files = (await fs.readdir(dir)).filter((f) => f.endsWith('.md'))
  const posts = await Promise.all(
    files.map(async (file) => {
      const { data, content } = matter(await fs.readFile(path.join(dir, file), 'utf8'))
      const parsed = Post.safeParse(data)
      if (!parsed.success) throw new Error(`${file}: ${parsed.error.message}`)
      return { slug: file.replace(/\.md$/, ''), data: parsed.data, content }
    }),
  )
  return posts.filter((p) => !p.data.draft).sort((a, b) => +b.data.date - +a.data.date)
}
