// content.config.ts
import { defineConfig, defineCollection } from '@pyreon/zero-content'
import { z } from 'zod'

export default defineConfig({
  collections: {
    blog: defineCollection({
      type: 'pages',
      schema: z.object({
        title: z.string(),
        description: z.string(),
        date: z.date(),
        tags: z.array(z.string()).default([]),
        draft: z.boolean().optional(),
      }),
      publishDate: 'date',  // dated in the future = unpublished until that day
      unpublished: 'omit',  // and not bundled at all in production
    }),
  },
})

