// src/examples/counter-button.tsx
import { signal, type Signal } from '@pyreon/reactivity'

export default function CounterButton(props: { shared?: Signal<number> }) {
  const count = props.shared ?? signal(0)
  return <button onClick={() => count.update((n) => n + 1)}>Clicked {() => count()} times</button>
}

// src/examples/counter-readout.tsx
import { signal, type Signal } from '@pyreon/reactivity'

export default function CounterReadout(props: { shared?: Signal<number> }) {
  const count = props.shared ?? signal(0)
  return <p>The other example says {() => count()}. Doubled: {() => count() * 2}</p>
}

